  ["a Skinning Knife, the beasts you kill on the way"] = "ein Kürschnermesser, die Tiere, die du unterwegs tötest",
  ["cloth from humanoids"] = "Stoff von Humanoiden",
  ["cloth from humanoids, for bandages"] = "Stoff von Humanoiden, für Verbände",
  ["meat or fish, and a cooking fire"] = "Fleisch oder Fisch und ein Kochfeuer",
  ["a Fishing Pole, water on the way"] = "eine Angelrute, Wasser unterwegs",

  -- quest tips (Fit.lua)
  ["First: Tender Strider Meat from the Plainstriders east of Bloodhoof, then put it down near Kyle (he runs around the village)"] = "Zuerst das Fleisch der Ebenenschreiter östlich von Bluthuf holen, dann in Kyles Nähe ablegen (er läuft durchs Dorf)",
  ["Kill the Rockjaw Troggs here as well: they count for A New Threat"] = "Töte hier auch die Troggs: sie zählen für die Trogg-Quest",
  ["Pick up Felix's crates on the way (A Refugee's Quandary): one by Talin's camp, one south of it, one at the cave"] = "Felix' Kisten unterwegs einsammeln: eine bei Talins Lager, eine südlich davon, eine bei der Höhle",
  ["A Task Unfinished (Mulgore): Antur Fallow stands up in the hills west of Camp Narache, the straight way runs into the mountains (Daniel 11.10.)"] = "Antur Fallow steht oben in den Hügeln westlich von Camp Narache, der direkte Weg läuft in die Berge",
  ["\"%s\" is a class quest you need: Leveldon takes you there now."] = "\"%s\" ist eine Klassenquest, die du brauchst: Leveldon bringt dich jetzt hin.",
  ["\"%s\" is not on your route (its objectives or its turn-in are far from it). It costs extra time; abandon it for the fastest way."] = "\"%s\" liegt nicht auf deiner Route (Ziele oder Abgabe sind weit weg). Das kostet Zeit; für den schnellsten Weg abbrechen.",
  ["\"%s\" fits your route: done along the way, turned in at a stop you pass anyway."] = "\"%s\" passt zur Route: unterwegs erledigt, abgegeben an einem Halt, an dem du ohnehin vorbeikommst.",
  -- (0.1.8) chapter path, speedrun line
  ["Level %d"] = "Stufe %d",
  ["Level %d in about %d min"] = "Stufe %d in ca. %d Min.",
  ["Level %d: almost there"] = "Stufe %d: gleich geschafft",
  ["Your time on this route. It stops when you do nothing for 2 minutes."] = "Deine Zeit auf dieser Route. Sie hält an, wenn du 2 Minuten nichts tust.",
  ["Green: ahead of the plan. Red: behind it."] = "Grün: vor dem Plan. Rot: dahinter.",
  ["Bars: your last level-ups, up ahead of the plan, down behind it."] = "Striche: deine letzten Stufenaufstiege, nach oben vor dem Plan, nach unten dahinter.",
  ["/lvd run: off  ·  /lvd run reset: start again"] = "/lvd run: aus  ·  /lvd run reset: neu starten",
  ["Level %d to %d  ·  step %d of %d"] = "Stufe %d bis %d  ·  Schritt %d von %d",
  ["Read the whole quest"] = "Die ganze Quest lesen",
  ["Shift-click a step: the same."] = "Shift-Klick auf einen Schritt geht auch.",
  ["Speedrun line"] = "Speedrun-Zeile",
  ["Your time on the route against the plan, the last level-ups, when the next level is due."] = "Deine Zeit auf der Route gegen den Plan, die letzten Stufenaufstiege und wann die nächste Stufe fällig ist.",
  ["Shift + mouse wheel: background opacity."] = "Shift + Mausrad: Deckkraft des Hintergrunds.",
  ["|cff3fa9f5Level|rdon: target markers "] = "|cff3fa9f5Level|rdon: Zielmarkierungen ",
  ["|cff3fa9f5Level|rdon: the marks over NPCs need the nameplates of friendly NPCs (interface options, Names)."] = "|cff3fa9f5Level|rdon: Für die Zeichen über NPCs bitte die Namensplaketten freundlicher NPCs einschalten (Interface-Optionen, Namen).",
  -- (17.10.) the options window (Options.lua)
  ["No background and frame"] = "Ohne Hintergrund und Rahmen",
  ["Hides the window's background, its frame and the boxes behind the chapter and the current step: only the text, the compass and the buttons up top stay."] = "Blendet den Hintergrund des Fensters, seinen Rahmen und die Kästen hinter Kapitel und aktuellem Schritt aus: Es bleiben nur Text, Kompass und die Knöpfe oben.",
  ["Compass in the current step"] = "Kompass im aktuellen Schritt",
  ["A compass beside the current step that points to its place. With it on, Questdon's own arrow steps aside while Leveldon's window is open."] = "Ein Kompass neben dem aktuellen Schritt, der zu seinem Ort zeigt. Solange Leveldons Fenster offen ist, tritt Questdons Pfeil dann zur Seite.",
  ["Your time on the route against the plan, the last level-ups and when the next level is due. The stopwatch button up top does the same."] = "Deine Zeit auf der Route gegen den Plan, die letzten Stufenaufstiege und wann die nächste Stufe fällig ist. Der Stoppuhr-Knopf oben macht dasselbe.",
  ["Markers over the next NPC"] = "Markierung über dem nächsten NPC",
  ["A marker over the head of the NPC or mob the current step is about."] = "Eine Markierung über dem Kopf des NPCs oder Gegners, um den es im aktuellen Schritt geht.",
  ["Hide the game's quest tracker"] = "Questliste des Spiels ausblenden",
  ["Leveldon and Questdon show your quests; the game's own list on the right goes away. A button in the quest log brings it back."] = "Leveldon und Questdon zeigen deine Quests, die Liste des Spiels rechts verschwindet. Ein Knopf im Questlog holt sie zurück.",
  ["Sleeping bag reminder"] = "Erinnerung an den Schlafsack",
  ["When you rest, a hint to lie in your sleeping bag for 3 minutes: 3 % more XP for 2 hours."] = "Beim Ausruhen ein Hinweis, dich 3 Minuten in den Schlafsack zu legen: 3 % mehr EP für 2 Stunden.",
  ["Campfire reminder"] = "Erinnerung an das Lagerfeuer",
  ["A hint to light a campfire for the camp bonuses when you have the materials."] = "Ein Hinweis, ein Lagerfeuer für die Lagerboni anzuzünden, wenn du die Materialien hast.",
  ["Dungeons in the route"] = "Dungeons in der Route",
  ["The route with the dungeons of your faction planned in (levels 1 to 30): their quests before, the run at its level, the turn-ins after. Off: no dungeons."] = "Die Route mit den Dungeons deiner Fraktion (Stufe 1 bis 30): vorher ihre Quests, der Lauf auf passender Stufe, danach die Abgaben. Aus: keine Dungeons.",
  ["Solo: no group or escort quests"] = "Solo: keine Gruppen- und Eskortquests",
  ["Leaves out quests for a group (elite) and escort quests. The route goes on without them."] = "Lässt Gruppenquests (Elite) und Eskortquests weg. Die Route geht ohne sie weiter.",
  ["Share route times"] = "Routenzeiten teilen",
  ["How the route goes for you (times per step, never names) goes to other Leveldon players through Questdon's channel, and theirs to you. It makes the plan better for everyone."] = "Wie die Route bei dir läuft (Zeiten pro Schritt, nie Namen), geht über Questdons Kanal an andere Leveldon-Spieler, und ihre an dich. So wird der Plan für alle besser.",
  ["Record your run"] = "Deinen Lauf aufzeichnen",
  ["Leveldon writes along how you play the route (steps, times, deaths, walking). Your reports and recordings help to fix the routes."] = "Leveldon schreibt mit, wie du die Route spielst (Schritte, Zeiten, Tode, Laufwege). Deine Meldungen und Aufzeichnungen helfen, die Routen zu verbessern.",
  ["Window"] = "Fenster",
  ["How Leveldon's window looks: background and frame, the compass and the markers."] = "Wie Leveldons Fenster aussieht: Hintergrund und Rahmen, Kompass und Markierungen.",
  ["Route"] = "Route",
  ["What the route plans in for you: dungeons, group quests, professions and the small XP helpers."] = "Was die Route für dich einplant: Dungeons, Gruppenquests, Berufe und die kleinen EP-Helfer.",
  ["Sharing and data"] = "Teilen und Daten",
  ["What Leveldon writes along and shares with other Leveldon players to make the routes better."] = "Was Leveldon mitschreibt und mit anderen Leveldon-Spielern teilt, um die Routen zu verbessern.",
  ["Help"] = "Hilfe",
  ["Your route and the commands."] = "Deine Route und die Befehle.",
  ["Open"] = "Öffnen",
  ["Export your recordings"] = "Aufzeichnungen exportieren",
  ["Skip"] = "Überspringen",
  ["Options"] = "Optionen",
  ["Pick the professions the route plans in: their trainers, tools and skill-ups come along the way."] = "Wähle die Berufe, die die Route einplant: Lehrer, Werkzeuge und Steigerungen kommen unterwegs mit.",
  ["Quest giver not there, route makes no sense, or a remark: it goes into your recording."] = "Questgeber nicht da, Route ergibt keinen Sinn oder eine Anmerkung: Es kommt in deine Aufzeichnung.",
  ["Your recordings and reports as text to copy, for a bug report."] = "Deine Aufzeichnungen und Meldungen als Text zum Kopieren, für einen Fehlerbericht.",
  ["The route goes on with the next step. Right-click a step for more."] = "Die Route geht mit dem nächsten Schritt weiter. Rechtsklick auf einen Schritt für mehr.",
  ["|cff3fa9f5Level|rdon: the options window needs Questdon 1.3.9 or newer. Until then: /lvd commands."] = "|cff3fa9f5Level|rdon: Das Optionsfenster braucht Questdon 1.3.9 oder neuer. Bis dahin: /lvd-Befehle.",
  ["/lvd: show or hide the window\n/lvd options: this window\n/lvd next, /lvd back: a step on or back\n/lvd report: report this step\n/lvd profs: professions\n/lvd line [name]: the start area of your route\n/lvd dungeons on|off, /lvd solo\n/lvd reset: start the route again from your level"] = "/lvd: Fenster zeigen oder verbergen\n/lvd options: dieses Fenster\n/lvd next, /lvd back: einen Schritt vor oder zurück\n/lvd report: diesen Schritt melden\n/lvd profs: Berufe\n/lvd line [name]: Startgebiet deiner Route\n/lvd dungeons on|off, /lvd solo\n/lvd reset: Route ab deiner Stufe neu starten",
  -- (21.10.) scrollable step list: the area block and the slider (StepList.lua)
  ["Also here"] = "Gleich hier",
  ["Coming steps"] = "Kommende Schritte",
  ["Mouse wheel or drag the slider: scroll the coming steps."] = "Mausrad oder Regler ziehen: die kommenden Schritte scrollen.",
  -- (21.10.) marks on bag items the route needs later (Bags.lua, Options)
  ["Mark items the route needs later"] = "Gegenstände markieren, die die Route später braucht",
  ["A blue frame on the items in your bags that a later quest of the route still needs, so you do not sell them by mistake. The item's tooltip says which quest."] = "Ein blauer Rahmen auf Gegenständen in deinen Taschen, die eine spätere Quest der Route noch braucht, damit du sie nicht aus Versehen verkaufst. Der Tooltip des Gegenstands nennt die Quest.",
  -- (22.10.) the route choice (Lines.lua, Options "Choose your route", /lvd line)
  ["Choose your route"] = "Route wählen",
  ["Your race starts in its own area. From there the route can go on through another start area of your faction (other quests, hours and reputation, e.g. Stormwind for a dwarf). You can change it in the middle of the route."] = "Deine Rasse beginnt in ihrem eigenen Gebiet. Von dort kann die Route durch ein anderes Startgebiet deiner Fraktion weitergehen (andere Quests, Dauer und Ruf, z. B. Sturmwind für einen Zwerg). Du kannst mitten in der Route wechseln.",
  [" via %s"] = " über %s",
  ["  route"] = "  Route",
  ["No other start areas for this character yet."] = "Für diesen Charakter gibt es noch keine anderen Startgebiete.",
  ["Your race starts in its own area. From there the route can go on through the start area of another race of your faction: other quests, other hours, other reputation."] = "Deine Rasse beginnt in ihrem eigenen Gebiet. Von dort kann die Route durch das Startgebiet einer anderen Rasse deiner Fraktion weitergehen: andere Quests, andere Dauer, anderer Ruf.",
  ["Route for levels 1 to 30"] = "Route für Stufe 1 bis 30",
  ["%s (your own)"] = "%s (dein eigenes)",
  ["%.1f h"] = "%.1f Std.",
  ["About %.1f hours, %d quests handed in"] = "Etwa %.1f Stunden, %d abgegebene Quests",
  ["With dungeons: about %.1f hours"] = "Mit Dungeons: etwa %.1f Stunden",
  ["This is your route."] = "Das ist deine Route.",
  ["Click: take this route from here on"] = "Klick: ab hier diese Route nehmen",
  ["%d quests"] = "%d Quests",
  ["%s +%s (stays %s)"] = "%s +%s (bleibt %s)",
  ["%s +%s: %s to %s"] = "%s +%s: %s auf %s",
  ["You can change it in the middle of the route: Leveldon goes on with the same step, or the first one you have not done yet. Levels 30 to 60 stay the same."] = "Du kannst mitten in der Route wechseln: Leveldon macht mit demselben Schritt weiter oder mit dem ersten, den du noch nicht gemacht hast. Stufe 30 bis 60 bleiben gleich.",
  ["Route: %s"] = "Route: %s",
  ["Unknown start area. Choose from: %s"] = "Unbekanntes Startgebiet. Zur Auswahl: %s",
  ["Elwynn Forest (Human)"] = "Wald von Elwynn (Mensch)",
  ["Dun Morogh (Dwarf, Gnome)"] = "Dun Morogh (Zwerg, Gnom)",
  ["Teldrassil (Night Elf)"] = "Teldrassil (Nachtelf)",
  ["Durotar (Orc, Troll)"] = "Durotar (Orc, Troll)",
  ["Mulgore (Tauren)"] = "Mulgore (Tauren)",
  ["Tirisfal (Undead)"] = "Tirisfal (Untote)",
  ["%s +%s"] = "%s +%s",
  ["Stormwind"] = "Sturmwind",
  ["Ironforge"] = "Eisenschmiede",
  ["Thunder Bluff"] = "Donnerfels",
  ["Undercity"] = "Unterstadt",
  ["Darkspear"] = "Dunkelspeer",
  -- (25.10.) only record (Options.lua SetRecordOnly)
  ["Only record your run"] = "Nur den Lauf aufzeichnen",
  ["On / off"] = "Ein / aus",
  ["Hides the window and switches off what Leveldon shows or marks by itself (markers over NPCs, bag frames, reminders); the recording and the shared route times stay on, so your run still helps the routes. Click again and the window and your settings are back. Also /lvd quiet."] = "Blendet das Fenster aus und schaltet ab, was Leveldon von selbst zeigt oder markiert (Marker über NPCs, Taschenrahmen, Erinnerungen); Aufzeichnung und geteilte Routenzeiten bleiben an, dein Lauf hilft also weiter den Routen. Noch ein Klick und Fenster und Einstellungen sind wieder da. Auch /lvd quiet.",
  ["|cff3fa9f5Level|rdon only records your run now. /lvd quiet brings the window and your settings back."] = "|cff3fa9f5Level|rdon zeichnet jetzt nur deinen Lauf auf. /lvd quiet holt Fenster und Einstellungen zurück.",
  ["|cff3fa9f5Level|rdon: window and settings are back."] = "|cff3fa9f5Level|rdon: Fenster und Einstellungen sind wieder da.",
  -- (25.10.) window values, key (Options.lua, Leveldon.lua)
  ["Lock window"] = "Fenster sperren",
  ["The window can no longer be dragged."] = "Das Fenster lässt sich nicht mehr verschieben.",
  ["Size"] = "Größe",
  ["Size of the whole window and its text. Ctrl + mouse wheel over the window does the same."] = "Größe des ganzen Fensters mit seinem Text. Strg + Mausrad über dem Fenster macht dasselbe.",
  ["Background opacity"] = "Hintergrund-Deckkraft",
  ["How dark the window's background is. Shift + mouse wheel over the window does the same."] = "Wie dunkel der Hintergrund des Fensters ist. Umschalt + Mausrad über dem Fenster macht dasselbe.",
  ["Dim in combat"] = "Im Kampf abdunkeln",
  ["The window fades to a little more than a third of its strength while you fight."] = "Das Fenster wird im Kampf auf etwas mehr als ein Drittel seiner Stärke abgedunkelt.",
  ["Reset window position"] = "Fensterposition zurücksetzen",
  ["Reset"] = "Zurücksetzen",
  ["Puts Leveldon's window back to its starting place. The key for it: Key Bindings > AddOns > Leveldon."] = "Setzt Leveldons Fenster an den Startplatz zurück. Die Taste dafür: Tastaturbelegung > AddOns > Leveldon.",
  ["Show or hide the window"] = "Fenster ein- oder ausblenden",
  -- (25.10.) arrow instead of the compass (Options.lua)
  ["Arrow instead of the compass"] = "Pfeil statt Kompass",
  ["Questdon's direction arrow leads you to the step instead of the compass in Leveldon's window and in the quest list. Switch off again and the compass and your earlier arrow settings come back. It changes Questdon's settings for all your characters."] = "Questdons Richtungspfeil führt dich zum Schritt, statt des Kompasses in Leveldons Fenster und in der Questliste. Wieder ausgeschaltet kommen der Kompass und deine früheren Pfeil-Einstellungen zurück. Es ändert Questdons Einstellungen für alle deine Charaktere.",
  ["Arrow: no background and frame"] = "Pfeil: ohne Hintergrund und Rahmen",
  ["Hides the plate and frame behind the arrow's text: only the arrow and the writing stay. Same as Questdon's option for the arrow."] = "Blendet die Platte und den Rahmen hinter dem Text des Pfeils aus: nur der Pfeil und die Schrift bleiben. Dasselbe wie Questdons Option für den Pfeil.",
  ["|cff3fa9f5Level|rdon: the arrow option needs Questdon 1.3.11 or newer."] = "|cff3fa9f5Level|rdon: die Pfeil-Option braucht Questdon 1.3.11 oder neuer.",
}


