  ["|cff3fa9f5Level|rdon: \"%s\" is not offered yet (level %d). The route goes on without it."] = "|cff3fa9f5Level|rdon : \"%s\" n'est pas encore proposée (niveau %d). L'itinéraire continue sans elle.",
  ["|cff3fa9f5Level|rdon: \"%s\" needs level %d. It comes back when the route passes this place again."] = "|cff3fa9f5Level|rdon : \"%s\" nécessite le niveau %d. Elle reviendra quand l'itinéraire repassera par ici.",
  ["|cff3fa9f5Level|rdon: \"%s\" skipped. One step back brings it back."] = "|cff3fa9f5Level|rdon : \"%s\" ignorée. Une étape en arrière la ramène.",
  ["|cff3fa9f5Level|rdon: %s took %d s (waited %d s), noted for /lvd export."] = "|cff3fa9f5Level|rdon : %s : %d s (attente : %d s), noté pour /lvd export.",
  ["|cff3fa9f5Level|rdon: before you go: "] = "|cff3fa9f5Level|rdon : avant de partir : ",
  ["|cff3fa9f5Level|rdon: before you go: only %d arrows or bullets."] = "|cff3fa9f5Level|rdon : avant de partir : seulement %d flèches ou balles.",
  ["|cff3fa9f5Level|rdon: campfire reminder "] = "|cff3fa9f5Level|rdon : rappel du feu de camp ",
  ["|cff3fa9f5Level|rdon: do not sell %s: the route needs it later."] = "|cff3fa9f5Level|rdon : ne vendez pas %s : l'itinéraire en aura besoin plus tard.",
  ["|cff3fa9f5Level|rdon: keep %s, the route needs it later for \"%s\" (bank it if your bags are full)."] = "|cff3fa9f5Level|rdon : gardez %s, l'itinéraire en aura besoin plus tard pour \"%s\" (mettez-le en banque si vos sacs sont pleins).",
  ["|cff3fa9f5Level|rdon: level %d: \"%s\" comes next (your class quest)."] = "|cff3fa9f5Level|rdon : niveau %d : \"%s\" vient ensuite (votre quête de classe).",
  ["|cff3fa9f5Level|rdon: lucky find, \"%s\" starts a quest chain: it is in your route now."] = "|cff3fa9f5Level|rdon : coup de chance, \"%s\" lance une chaîne de quêtes : elle est maintenant dans votre itinéraire.",
  ["|cff3fa9f5Level|rdon: nothing important here now; the %d spells are your choice (the gold goes to riding at 40)."] = "|cff3fa9f5Level|rdon : rien d'important ici pour l'instant ; les %d sorts sont à votre choix (l'or va à la monte au niveau 40).",
  ["|cff3fa9f5Level|rdon: nothing important here now; the spell is your choice (the gold goes to riding at 40)."] = "|cff3fa9f5Level|rdon : rien d'important ici pour l'instant ; le sort est à votre choix (l'or va à la monte au niveau 40).",
  ["|cff3fa9f5Level|rdon: report saved ("] = "|cff3fa9f5Level|rdon : signalement enregistré (",
  ["|cff3fa9f5Level|rdon: riding costs %s, you still need %s. The route goes on on foot; Leveldon tells you when you have it."] = "|cff3fa9f5Level|rdon : la monte coûte %s, il vous manque encore %s. L'itinéraire continue à pied ; Leveldon vous prévient quand vous l'aurez.",
  ["|cff3fa9f5Level|rdon: route started again from your level."] = "|cff3fa9f5Level|rdon : itinéraire relancé depuis votre niveau.",
  ["|cff3fa9f5Level|rdon: sharing %s (sent %d, received %d facts, %d kept). /lvd share on|off"] = "|cff3fa9f5Level|rdon : partage %s (envoyés %d, reçus %d faits, %d conservés). /lvd share on|off",
  ["|cff3fa9f5Level|rdon: sleeping bag reminder "] = "|cff3fa9f5Level|rdon : rappel du sac de couchage ",
  ["|cff3fa9f5Level|rdon: solo "] = "|cff3fa9f5Level|rdon : solo ",
  ["|cff3fa9f5Level|rdon: target markers "] = "|cff3fa9f5Level|rdon : marqueurs de cible ",
  ["|cff3fa9f5Level|rdon: text size %d %% (Ctrl + mouse wheel over the title bar, /lvd text 1.3)."] = "|cff3fa9f5Level|rdon : taille du texte %d %% (Ctrl + molette au-dessus de la barre de titre, /lvd text 1.3).",
  ["|cff3fa9f5Level|rdon: the marks over NPCs need the nameplates of friendly NPCs (interface options, Names)."] = "|cff3fa9f5Level|rdon : pour les marques au-dessus des PNJ, activez les barres de nom des PNJ amicaux (options de l'interface, Noms).",
  ["|cff3fa9f5Level|rdon: the options window needs Questdon 1.3.9 or newer. Until then: /lvd commands."] = "|cff3fa9f5Level|rdon : la fenêtre d'options nécessite Questdon 1.3.9 ou plus récent. D'ici là : commandes /lvd.",
  ["|cff3fa9f5Level|rdon: writing along %s. %d sessions, %d events, %d walking points, %d reports kept (/lvd rec on|off)."] = "|cff3fa9f5Level|rdon : enregistrement en cours %s. %d sessions, %d événements, %d points de trajet, %d signalements conservés (/lvd rec on|off).",
  ["|cff3fa9f5Level|rdon: you are ahead on the route; it goes on at \"%s\"."] = "|cff3fa9f5Level|rdon : vous êtes en avance sur l'itinéraire ; il continue à \"%s\".",
  ["|cff3fa9f5Level|rdon: you have the %s for riding now: visit the riding trainer."] = "|cff3fa9f5Level|rdon : vous avez maintenant les %s nécessaires pour la monte : allez voir l'instructeur d'équitation.",
  ["|cff3fa9f5Level|rdon: you learned %s: its steps are in your route now."] = "|cff3fa9f5Level|rdon : vous avez appris %s : ses étapes sont maintenant dans votre itinéraire.",
  -- (25.10.) only record (Options.lua SetRecordOnly)
  ["Only record your run"] = "Seulement enregistrer votre parcours",
  ["On / off"] = "Oui / non",
  ["Hides the window and switches off what Leveldon shows or marks by itself (markers over NPCs, bag frames, reminders); the recording and the shared route times stay on, so your run still helps the routes. Click again and the window and your settings are back. Also /lvd quiet."] = "Masque la fenêtre et désactive ce que Leveldon affiche ou marque de lui-même (marqueurs au-dessus des PNJ, cadres dans les sacs, rappels) ; l'enregistrement et le partage des temps de route restent actifs, votre parcours aide donc toujours les routes. Un autre clic et la fenêtre et vos réglages reviennent. Aussi /lvd quiet.",
  ["|cff3fa9f5Level|rdon only records your run now. /lvd quiet brings the window and your settings back."] = "|cff3fa9f5Level|rdon ne fait plus qu'enregistrer votre parcours. /lvd quiet rétablit la fenêtre et vos réglages.",
  ["|cff3fa9f5Level|rdon: window and settings are back."] = "|cff3fa9f5Level|rdon : fenêtre et réglages rétablis.",
  -- (25.10.) window values, key (Options.lua, Leveldon.lua)
  ["Lock window"] = "Verrouiller la fenêtre",
  ["The window can no longer be dragged."] = "La fenêtre ne peut plus être déplacée.",
  ["Size"] = "Taille",
  ["Size of the whole window and its text. Ctrl + mouse wheel over the window does the same."] = "Taille de toute la fenêtre et de son texte. Ctrl + molette sur la fenêtre fait la même chose.",
  ["Background opacity"] = "Opacité du fond",
  ["How dark the window's background is. Shift + mouse wheel over the window does the same."] = "Degré d'obscurité du fond de la fenêtre. Maj + molette sur la fenêtre fait la même chose.",
  ["Dim in combat"] = "Atténuer en combat",
  ["The window fades to a little more than a third of its strength while you fight."] = "La fenêtre s'atténue à un peu plus d'un tiers de son intensité pendant le combat.",
  ["Reset window position"] = "Réinitialiser la position de la fenêtre",
  ["Reset"] = "Réinitialiser",
  ["Puts Leveldon's window back to its starting place. The key for it: Key Bindings > AddOns > Leveldon."] = "Remet la fenêtre de Leveldon à sa place de départ. La touche : Raccourcis > AddOns > Leveldon.",
  ["Show or hide the window"] = "Afficher ou masquer la fenêtre",
  -- (25.10.) arrow instead of the compass (Options.lua)
  ["Arrow instead of the compass"] = "Flèche au lieu de la boussole",
  ["Questdon's direction arrow leads you to the step instead of the compass in Leveldon's window and in the quest list. Switch off again and the compass and your earlier arrow settings come back. It changes Questdon's settings for all your characters."] = "La flèche de direction de Questdon vous mène à l'étape à la place de la boussole dans la fenêtre de Leveldon et dans la liste de quêtes. Désactivée, la boussole et vos anciens réglages de flèche reviennent. Cela modifie les réglages de Questdon pour tous vos personnages.",
  ["Arrow: no background and frame"] = "Flèche : sans fond ni cadre",
  ["Hides the plate and frame behind the arrow's text: only the arrow and the writing stay. Same as Questdon's option for the arrow."] = "Masque la plaque et le cadre derrière le texte de la flèche : seuls la flèche et l'écriture restent. Identique à l'option de Questdon pour la flèche.",
  ["|cff3fa9f5Level|rdon: the arrow option needs Questdon 1.3.11 or newer."] = "|cff3fa9f5Level|rdon : l'option de flèche nécessite Questdon 1.3.11 ou plus récent.",
}
