  ["What the route plans in for you: dungeons, group quests, professions and the small XP helpers."] = "Lo que la ruta incluye para ti: mazmorras, misiones de grupo, profesiones y las pequeñas ayudas de XP.",
  ["When you rest, a hint to lie in your sleeping bag for 3 minutes: 3 % more XP for 2 hours."] = "Cuando descansas, un aviso para tumbarte 3 minutos en tu saco de dormir: XP +3 % durante 2 horas.",
  ["Window"] = "Ventana",
  ["Window size"] = "Tamaño de la ventana",
  ["With dungeons: about %.1f hours"] = "Con mazmorras: unas %.1f horas",
