  ["|cff3fa9f5Level|rdon recommends: %s (%s). The other spell is your choice: the gold goes to riding at 40."] = "|cff3fa9f5Level|rdon recomienda: %s (%s). El otro hechizo lo eliges tú: el oro se destina a equitación a nivel 40.",
  ["|cff3fa9f5Level|rdon: \"%s\" is in your route now, along the way."] = "|cff3fa9f5Level|rdon: \"%s\" está ahora en tu ruta, de paso.",
  ["|cff3fa9f5Level|rdon: \"%s\" is not offered yet (level %d). The route goes on without it."] = "|cff3fa9f5Level|rdon: \"%s\" aún no se ofrece (nivel %d). La ruta continúa sin ella.",
  ["|cff3fa9f5Level|rdon: \"%s\" needs level %d. It comes back when the route passes this place again."] = "|cff3fa9f5Level|rdon: \"%s\" necesita nivel %d. Volverá cuando la ruta pase de nuevo por este lugar.",
