  ["|cff3fa9f5Level|rdon: keep %s, the route needs it later for \"%s\" (bank it if your bags are full)."] = "|cff3fa9f5Level|rdon: guarda %s, la ruta lo necesita más tarde para \"%s\" (déjalo en el banco si tus bolsas están llenas).",
  ["|cff3fa9f5Level|rdon: level %d: \"%s\" comes next (your class quest)."] = "|cff3fa9f5Level|rdon: nivel %d: \"%s\" viene a continuación (tu misión de clase).",
  ["|cff3fa9f5Level|rdon: lucky find, \"%s\" starts a quest chain: it is in your route now."] = "|cff3fa9f5Level|rdon: ¡suerte!, \"%s\" inicia una cadena de misiones: ya está en tu ruta.",
  ["|cff3fa9f5Level|rdon: nothing important here now; the %d spells are your choice (the gold goes to riding at 40)."] = "|cff3fa9f5Level|rdon: ahora no hay nada importante aquí; los %d hechizos los eliges tú (el oro se destina a equitación a nivel 40).",
  ["|cff3fa9f5Level|rdon: nothing important here now; the spell is your choice (the gold goes to riding at 40)."] = "|cff3fa9f5Level|rdon: ahora no hay nada importante aquí; el hechizo lo eliges tú (el oro se destina a equitación a nivel 40).",
  ["|cff3fa9f5Level|rdon: report saved ("] = "|cff3fa9f5Level|rdon: reporte guardado (",
  ["|cff3fa9f5Level|rdon: riding costs %s, you still need %s. The route goes on on foot; Leveldon tells you when you have it."] = "|cff3fa9f5Level|rdon: la equitación cuesta %s, aún te faltan %s. La ruta sigue a pie; Leveldon te avisa cuando lo tengas.",
  ["|cff3fa9f5Level|rdon: route started again from your level."] = "|cff3fa9f5Level|rdon: ruta reiniciada desde tu nivel.",
  ["|cff3fa9f5Level|rdon: sharing %s (sent %d, received %d facts, %d kept). /lvd share on|off"] = "|cff3fa9f5Level|rdon: compartir %s (enviados %d, recibidos %d datos, %d guardados). /lvd share on|off",
