  ["|cff3fa9f5Level|rdon: solo "] = "|cff3fa9f5Level|rdon: en solitario ",
  ["|cff3fa9f5Level|rdon: target markers "] = "|cff3fa9f5Level|rdon: marcas de objetivo ",
  ["|cff3fa9f5Level|rdon: text size %d %% (Ctrl + mouse wheel over the title bar, /lvd text 1.3)."] = "|cff3fa9f5Level|rdon: tamaño del texto %d %% (Ctrl + rueda del mouse sobre la barra de título, /lvd text 1.3).",
  ["|cff3fa9f5Level|rdon: the marks over NPCs need the nameplates of friendly NPCs (interface options, Names)."] = "|cff3fa9f5Level|rdon: para las marcas sobre los PNJ activa las placas de nombre de los PNJ amistosos (opciones de interfaz, Nombres).",
  ["|cff3fa9f5Level|rdon: the options window needs Questdon 1.3.9 or newer. Until then: /lvd commands."] = "|cff3fa9f5Level|rdon: la ventana de opciones necesita Questdon 1.3.9 o superior. Hasta entonces: comandos /lvd.",
  ["|cff3fa9f5Level|rdon: writing along %s. %d sessions, %d events, %d walking points, %d reports kept (/lvd rec on|off)."] = "|cff3fa9f5Level|rdon: grabando %s. %d sesiones, %d eventos, %d puntos de recorrido, %d reportes guardados (/lvd rec on|off).",
  ["|cff3fa9f5Level|rdon: you are ahead on the route; it goes on at \"%s\"."] = "|cff3fa9f5Level|rdon: vas por delante en la ruta; continúa en \"%s\".",
  ["|cff3fa9f5Level|rdon: you have the %s for riding now: visit the riding trainer."] = "|cff3fa9f5Level|rdon: ya tienes los %s para la equitación: visita al instructor de equitación.",
  ["|cff3fa9f5Level|rdon: you learned %s: its steps are in your route now."] = "|cff3fa9f5Level|rdon: has aprendido %s: sus pasos ya están en tu ruta.",
  -- (25.10.) only record (Options.lua SetRecordOnly)
  ["Only record your run"] = "Solo grabar tu recorrido",
  ["On / off"] = "Sí / no",
  ["Hides the window and switches off what Leveldon shows or marks by itself (markers over NPCs, bag frames, reminders); the recording and the shared route times stay on, so your run still helps the routes. Click again and the window and your settings are back. Also /lvd quiet."] = "Oculta la ventana y desactiva lo que Leveldon muestra o marca por sí solo (marcadores sobre PNJ, marcos en las bolsas, recordatorios); la grabación y los tiempos de ruta compartidos siguen activos, así que tu recorrido sigue ayudando a las rutas. Otro clic y vuelven la ventana y tus ajustes. También /lvd quiet.",
  ["|cff3fa9f5Level|rdon only records your run now. /lvd quiet brings the window and your settings back."] = "|cff3fa9f5Level|rdon ahora solo graba tu recorrido. /lvd quiet recupera la ventana y tus ajustes.",
  ["|cff3fa9f5Level|rdon: window and settings are back."] = "|cff3fa9f5Level|rdon: la ventana y los ajustes han vuelto.",
  -- (25.10.) window values, key (Options.lua, Leveldon.lua)
  ["Lock window"] = "Bloquear ventana",
  ["The window can no longer be dragged."] = "La ventana ya no se puede mover.",
  ["Size"] = "Tamaño",
  ["Size of the whole window and its text. Ctrl + mouse wheel over the window does the same."] = "Tamaño de toda la ventana y su texto. Ctrl + rueda del ratón sobre la ventana hace lo mismo.",
  ["Background opacity"] = "Opacidad del fondo",
  ["How dark the window's background is. Shift + mouse wheel over the window does the same."] = "Lo oscuro que es el fondo de la ventana. Mayús + rueda del ratón sobre la ventana hace lo mismo.",
  ["Dim in combat"] = "Atenuar en combate",
  ["The window fades to a little more than a third of its strength while you fight."] = "La ventana se atenúa a algo más de un tercio de su intensidad durante el combate.",
  ["Reset window position"] = "Restablecer posición de la ventana",
  ["Reset"] = "Restablecer",
  ["Puts Leveldon's window back to its starting place. The key for it: Key Bindings > AddOns > Leveldon."] = "Devuelve la ventana de Leveldon a su sitio inicial. La tecla: Asignación de teclas > AddOns > Leveldon.",
  ["Show or hide the window"] = "Mostrar u ocultar la ventana",
  -- (25.10.) arrow instead of the compass (Options.lua)
  ["Arrow instead of the compass"] = "Flecha en lugar de la brújula",
  ["Questdon's direction arrow leads you to the step instead of the compass in Leveldon's window and in the quest list. Switch off again and the compass and your earlier arrow settings come back. It changes Questdon's settings for all your characters."] = "La flecha de dirección de Questdon te guía al paso en lugar de la brújula en la ventana de Leveldon y en la lista de misiones. Al desactivarla vuelven la brújula y tus ajustes anteriores de la flecha. Cambia los ajustes de Questdon para todos tus personajes.",
  ["Arrow: no background and frame"] = "Flecha: sin fondo ni marco",
  ["Hides the plate and frame behind the arrow's text: only the arrow and the writing stay. Same as Questdon's option for the arrow."] = "Oculta la placa y el marco detrás del texto de la flecha: solo quedan la flecha y la escritura. Igual que la opción de Questdon para la flecha.",
  ["|cff3fa9f5Level|rdon: the arrow option needs Questdon 1.3.11 or newer."] = "|cff3fa9f5Level|rdon: la opción de la flecha necesita Questdon 1.3.11 o posterior.",
}
