  ["|cff3fa9f5Level|rdon: campfire reminder "] = "|cff3fa9f5Level|rdon: lembrete da fogueira ",
  ["|cff3fa9f5Level|rdon: do not sell %s: the route needs it later."] = "|cff3fa9f5Level|rdon: não venda %s: a rota precisa disso depois.",
