  ["|cff3fa9f5Level|rdon: level %d: \"%s\" comes next (your class quest)."] = "|cff3fa9f5Level|rdon: nível %d: \"%s\" vem a seguir (sua missão de classe).",
  ["|cff3fa9f5Level|rdon: lucky find, \"%s\" starts a quest chain: it is in your route now."] = "|cff3fa9f5Level|rdon: golpe de sorte, \"%s\" inicia uma cadeia de missões: ela está na sua rota agora.",
  ["|cff3fa9f5Level|rdon: nothing important here now; the %d spells are your choice (the gold goes to riding at 40)."] = "|cff3fa9f5Level|rdon: nada importante aqui agora; os %d feitiços são escolha sua (o ouro vai para a equitação no 40).",
  ["|cff3fa9f5Level|rdon: nothing important here now; the spell is your choice (the gold goes to riding at 40)."] = "|cff3fa9f5Level|rdon: nada importante aqui agora; o feitiço é escolha sua (o ouro vai para a equitação no 40).",
  ["|cff3fa9f5Level|rdon: report saved ("] = "|cff3fa9f5Level|rdon: relatório salvo (",
  ["|cff3fa9f5Level|rdon: riding costs %s, you still need %s. The route goes on on foot; Leveldon tells you when you have it."] = "|cff3fa9f5Level|rdon: a equitação custa %s, você ainda precisa de %s. A rota continua a pé; o Leveldon avisa quando você tiver.",
  ["|cff3fa9f5Level|rdon: route started again from your level."] = "|cff3fa9f5Level|rdon: rota reiniciada a partir do seu nível.",
  ["|cff3fa9f5Level|rdon: sharing %s (sent %d, received %d facts, %d kept). /lvd share on|off"] = "|cff3fa9f5Level|rdon: compartilhamento %s (enviados %d, recebidos %d dados, %d mantidos). /lvd share on|off",
  ["|cff3fa9f5Level|rdon: sleeping bag reminder "] = "|cff3fa9f5Level|rdon: lembrete do saco de dormir ",
  ["|cff3fa9f5Level|rdon: solo "] = "|cff3fa9f5Level|rdon: solo ",
  ["|cff3fa9f5Level|rdon: target markers "] = "|cff3fa9f5Level|rdon: marcas de alvo ",
  ["|cff3fa9f5Level|rdon: text size %d %% (Ctrl + mouse wheel over the title bar, /lvd text 1.3)."] = "|cff3fa9f5Level|rdon: tamanho do texto %d %% (Ctrl + roda do mouse sobre a barra de título, /lvd text 1.3).",
  ["|cff3fa9f5Level|rdon: the marks over NPCs need the nameplates of friendly NPCs (interface options, Names)."] = "|cff3fa9f5Level|rdon: para as marcas sobre os NPCs, ative as placas de identificação de NPCs amigáveis (opções de interface, Nomes).",
  ["|cff3fa9f5Level|rdon: the options window needs Questdon 1.3.9 or newer. Until then: /lvd commands."] = "|cff3fa9f5Level|rdon: a janela de opções precisa do Questdon 1.3.9 ou mais novo. Até lá: comandos /lvd.",
  ["|cff3fa9f5Level|rdon: writing along %s. %d sessions, %d events, %d walking points, %d reports kept (/lvd rec on|off)."] = "|cff3fa9f5Level|rdon: gravando %s. %d sessões, %d eventos, %d pontos de trajeto, %d relatórios mantidos (/lvd rec on|off).",
  ["|cff3fa9f5Level|rdon: you are ahead on the route; it goes on at \"%s\"."] = "|cff3fa9f5Level|rdon: você está à frente na rota; ela continua em \"%s\".",
  ["|cff3fa9f5Level|rdon: you have the %s for riding now: visit the riding trainer."] = "|cff3fa9f5Level|rdon: você já tem os %s para a equitação: visite o instrutor de equitação.",
  ["|cff3fa9f5Level|rdon: you learned %s: its steps are in your route now."] = "|cff3fa9f5Level|rdon: você aprendeu %s: os passos dela já estão na sua rota.",
  -- (25.10.) only record (Options.lua SetRecordOnly)
  ["Only record your run"] = "Apenas gravar sua jornada",
  ["On / off"] = "Ligar / desligar",
  ["Hides the window and switches off what Leveldon shows or marks by itself (markers over NPCs, bag frames, reminders); the recording and the shared route times stay on, so your run still helps the routes. Click again and the window and your settings are back. Also /lvd quiet."] = "Oculta a janela e desliga o que o Leveldon mostra ou marca sozinho (marcadores sobre PNJs, molduras nas bolsas, lembretes); a gravação e os tempos de rota compartilhados continuam ligados, então sua jornada ainda ajuda as rotas. Outro clique e a janela e suas configurações voltam. Também /lvd quiet.",
  ["|cff3fa9f5Level|rdon only records your run now. /lvd quiet brings the window and your settings back."] = "|cff3fa9f5Level|rdon agora só grava sua jornada. /lvd quiet traz a janela e suas configurações de volta.",
  ["|cff3fa9f5Level|rdon: window and settings are back."] = "|cff3fa9f5Level|rdon: janela e configurações de volta.",
  -- (25.10.) window values, key (Options.lua, Leveldon.lua)
  ["Lock window"] = "Travar janela",
  ["The window can no longer be dragged."] = "A janela não pode mais ser movida.",
  ["Size"] = "Tamanho",
  ["Size of the whole window and its text. Ctrl + mouse wheel over the window does the same."] = "Tamanho de toda a janela e do seu texto. Ctrl + roda do mouse sobre a janela faz o mesmo.",
  ["Background opacity"] = "Opacidade do fundo",
  ["How dark the window's background is. Shift + mouse wheel over the window does the same."] = "Quão escuro é o fundo da janela. Shift + roda do mouse sobre a janela faz o mesmo.",
  ["Dim in combat"] = "Escurecer em combate",
  ["The window fades to a little more than a third of its strength while you fight."] = "A janela escurece para um pouco mais de um terço da intensidade durante o combate.",
  ["Reset window position"] = "Redefinir posição da janela",
  ["Reset"] = "Redefinir",
  ["Puts Leveldon's window back to its starting place. The key for it: Key Bindings > AddOns > Leveldon."] = "Coloca a janela do Leveldon de volta no lugar inicial. A tecla: Atalhos > AddOns > Leveldon.",
  ["Show or hide the window"] = "Mostrar ou ocultar a janela",
  -- (25.10.) arrow instead of the compass (Options.lua)
  ["Arrow instead of the compass"] = "Seta em vez da bússola",
  ["Questdon's direction arrow leads you to the step instead of the compass in Leveldon's window and in the quest list. Switch off again and the compass and your earlier arrow settings come back. It changes Questdon's settings for all your characters."] = "A seta de direção do Questdon leva você ao passo em vez da bússola na janela do Leveldon e na lista de missões. Ao desligar, a bússola e suas configurações anteriores da seta voltam. Isso altera as configurações do Questdon para todos os seus personagens.",
  ["Arrow: no background and frame"] = "Seta: sem fundo e moldura",
  ["Hides the plate and frame behind the arrow's text: only the arrow and the writing stay. Same as Questdon's option for the arrow."] = "Oculta a placa e a moldura atrás do texto da seta: ficam só a seta e a escrita. Igual à opção do Questdon para a seta.",
  ["|cff3fa9f5Level|rdon: the arrow option needs Questdon 1.3.11 or newer."] = "|cff3fa9f5Level|rdon: a opção da seta precisa do Questdon 1.3.11 ou mais novo.",
}
