  ["|cff3fa9f5Level|rdon: route started again from your level."] = "|cff3fa9f5Level|rdon: маршрут запущен заново с вашего уровня.",
  ["|cff3fa9f5Level|rdon: sharing %s (sent %d, received %d facts, %d kept). /lvd share on|off"] = "|cff3fa9f5Level|rdon: обмен %s (отправлено %d, получено %d фактов, сохранено %d). /lvd share on|off",
  ["|cff3fa9f5Level|rdon: sleeping bag reminder "] = "|cff3fa9f5Level|rdon: напоминание о спальном мешке ",
  ["|cff3fa9f5Level|rdon: solo "] = "|cff3fa9f5Level|rdon: соло ",
  ["|cff3fa9f5Level|rdon: target markers "] = "|cff3fa9f5Level|rdon: метки целей ",
  ["|cff3fa9f5Level|rdon: text size %d %% (Ctrl + mouse wheel over the title bar, /lvd text 1.3)."] = "|cff3fa9f5Level|rdon: размер текста %d %% (Ctrl + колесико мыши над строкой заголовка, /lvd text 1.3).",
  ["|cff3fa9f5Level|rdon: the marks over NPCs need the nameplates of friendly NPCs (interface options, Names)."] = "|cff3fa9f5Level|rdon: для меток над NPC включите индикаторы здоровья дружественных NPC (параметры интерфейса, Имена).",
  ["|cff3fa9f5Level|rdon: the options window needs Questdon 1.3.9 or newer. Until then: /lvd commands."] = "|cff3fa9f5Level|rdon: для окна параметров нужен Questdon 1.3.9 или новее. А пока: команды /lvd.",
  ["|cff3fa9f5Level|rdon: writing along %s. %d sessions, %d events, %d walking points, %d reports kept (/lvd rec on|off)."] = "|cff3fa9f5Level|rdon: запись %s. Сессий: %d, событий: %d, точек пути: %d, отчетов сохранено: %d (/lvd rec on|off).",
  ["|cff3fa9f5Level|rdon: you are ahead on the route; it goes on at \"%s\"."] = "|cff3fa9f5Level|rdon: вы впереди маршрута; он продолжается на \"%s\".",
  ["|cff3fa9f5Level|rdon: you have the %s for riding now: visit the riding trainer."] = "|cff3fa9f5Level|rdon: у вас теперь есть %s на верховую езду: зайдите к учителю верховой езды.",
  ["|cff3fa9f5Level|rdon: you learned %s: its steps are in your route now."] = "|cff3fa9f5Level|rdon: вы выучили %s: его шаги теперь в вашем маршруте.",
  -- (25.10.) only record (Options.lua SetRecordOnly)
  ["Only record your run"] = "Только записывать прохождение",
  ["On / off"] = "Вкл / выкл",
  ["Hides the window and switches off what Leveldon shows or marks by itself (markers over NPCs, bag frames, reminders); the recording and the shared route times stay on, so your run still helps the routes. Click again and the window and your settings are back. Also /lvd quiet."] = "Скрывает окно и отключает то, что Leveldon сам показывает или отмечает (метки над НИП, рамки в сумках, напоминания); запись и общие времена маршрута остаются включены, так что ваше прохождение по-прежнему помогает маршрутам. Ещё один щелчок, и окно и настройки вернутся. Также /lvd quiet.",
  ["|cff3fa9f5Level|rdon only records your run now. /lvd quiet brings the window and your settings back."] = "|cff3fa9f5Level|rdon теперь только записывает ваше прохождение. /lvd quiet вернёт окно и настройки.",
  ["|cff3fa9f5Level|rdon: window and settings are back."] = "|cff3fa9f5Level|rdon: окно и настройки восстановлены.",
  -- (25.10.) window values, key (Options.lua, Leveldon.lua)
  ["Lock window"] = "Закрепить окно",
  ["The window can no longer be dragged."] = "Окно больше нельзя перемещать.",
  ["Size"] = "Размер",
  ["Size of the whole window and its text. Ctrl + mouse wheel over the window does the same."] = "Размер всего окна и его текста. Ctrl + колесо мыши над окном делает то же самое.",
  ["Background opacity"] = "Непрозрачность фона",
  ["How dark the window's background is. Shift + mouse wheel over the window does the same."] = "Насколько тёмным будет фон окна. Shift + колесо мыши над окном делает то же самое.",
  ["Dim in combat"] = "Затемнять в бою",
  ["The window fades to a little more than a third of its strength while you fight."] = "В бою окно тускнеет чуть больше чем до трети своей яркости.",
  ["Reset window position"] = "Сбросить положение окна",
  ["Reset"] = "Сбросить",
  ["Puts Leveldon's window back to its starting place. The key for it: Key Bindings > AddOns > Leveldon."] = "Возвращает окно Leveldon на начальное место. Клавиша: Назначение клавиш > Дополнения > Leveldon.",
  ["Show or hide the window"] = "Показать или скрыть окно",
  -- (25.10.) arrow instead of the compass (Options.lua)
  ["Arrow instead of the compass"] = "Стрелка вместо компаса",
  ["Questdon's direction arrow leads you to the step instead of the compass in Leveldon's window and in the quest list. Switch off again and the compass and your earlier arrow settings come back. It changes Questdon's settings for all your characters."] = "Стрелка направления Questdon ведёт вас к шагу вместо компаса в окне Leveldon и в списке заданий. При выключении компас и ваши прежние настройки стрелки возвращаются. Это меняет настройки Questdon для всех ваших персонажей.",
  ["Arrow: no background and frame"] = "Стрелка: без фона и рамки",
  ["Hides the plate and frame behind the arrow's text: only the arrow and the writing stay. Same as Questdon's option for the arrow."] = "Скрывает плашку и рамку за текстом стрелки: остаются только стрелка и надпись. То же, что параметр Questdon для стрелки.",
  ["|cff3fa9f5Level|rdon: the arrow option needs Questdon 1.3.11 or newer."] = "|cff3fa9f5Level|rdon: для параметра стрелки нужен Questdon 1.3.11 или новее.",
}
