  ["%s sells %s: buy it now"] = "%s에서 판매 중: %s, 지금 구매하세요",
  ["%s: %.1f MB, about %d KB new memory a second"] = "%s: %.1f MB, 초당 약 %d KB의 새 메모리",
  ["%s: buy later, you need %s"] = "%s: 나중에 구매, 필요: %s",
  [", buy ammunition"] = ", 탄약을 구매하세요",
  [", none planned for this character yet"] = ", 이 캐릭터는 아직 계획된 것이 없습니다",
  ["/lvd run: off  ·  /lvd run reset: start again"] = "/lvd run: 끔  ·  /lvd run reset: 다시 시작",
  ["/lvd: show or hide the window\n/lvd options: this window\n/lvd next, /lvd back: a step on or back\n/lvd report: report this step\n/lvd profs: professions\n/lvd line [name]: the start area of your route\n/lvd dungeons on|off, /lvd solo\n/lvd reset: start the route again from your level"] = "/lvd: 창 표시 또는 숨기기\n/lvd options: 이 창\n/lvd next, /lvd back: 한 단계 앞으로 또는 뒤로\n/lvd report: 이 단계 신고\n/lvd profs: 전문 기술\n/lvd line [name]: 경로의 시작 지역\n/lvd dungeons on|off, /lvd solo\n/lvd reset: 현재 레벨부터 경로 다시 시작",
  ["; %d more spells are your choice (saving for riding)"] = "; 주문 %d개 더는 직접 선택 (기마술을 위해 저축)",
  ["A Task Unfinished (Mulgore): Antur Fallow stands up in the hills west of Camp Narache, the straight way runs into the mountains (Daniel 11.10.)"] = "A Task Unfinished (Mulgore): Antur Fallow는 나라체 야영지 서쪽 언덕 위에 있으며, 곧장 가는 길은 산으로 이어집니다",
  ["A blue frame on the items in your bags that a later quest of the route still needs, so you do not sell them by mistake. The item's tooltip says which quest."] = "경로의 이후 퀘스트에 아직 필요한 가방 속 아이템에 파란 테두리를 표시해, 실수로 팔지 않게 합니다. 아이템 툴팁에 퀘스트가 나옵니다.",
  ["A compass beside the current step that points to its place. With it on, Questdon's own arrow steps aside while Leveldon's window is open."] = "현재 단계 옆에 그 위치를 가리키는 나침반을 표시합니다. 켜면 Leveldon 창이 열려 있는 동안 Questdon의 화살표는 비켜 줍니다.",
  ["A hint to light a campfire for the camp bonuses when you have the materials."] = "재료가 있을 때 야영 보너스를 위해 모닥불을 피우라는 알림입니다.",
  ["A marker over the head of the NPC or mob the current step is about."] = "현재 단계와 관련된 NPC나 몬스터의 머리 위에 표시를 합니다.",
  ["About %.1f hours, %d quests handed in"] = "약 %.1f시간, 퀘스트 %d개 완료",
  ["Accept"] = "수락",
  ["Along here: %s"] = "가는 길에: %s",
  ["Already learned: %s"] = "이미 배움: %s",
  ["Also here"] = "여기에도",
  ["Bars: your last level-ups, up ahead of the plan, down behind it."] = "막대: 최근 레벨 업, 위쪽은 계획보다 빠름, 아래쪽은 느림.",
  ["Blizzard's quest tracker: hidden"] = "Blizzard 퀘스트 추적기: 숨김",
  ["Blizzard's quest tracker: shown"] = "Blizzard 퀘스트 추적기: 표시",
  ["Buy"] = "구매",
  ["Buy %s from %s%s"] = "구매: %s, 판매자 %s%s",
  ["Campfire reminder"] = "모닥불 알림",
  ["Cancel"] = "취소",
  ["Chapter: "] = "챕터: ",
  ["Choose your professions"] = "전문 기술 선택",
  ["Choose your route"] = "경로 선택",
  ["Click: pick or drop it"] = "클릭: 선택 또는 해제",
  ["Click: take this route from here on"] = "클릭: 여기서부터 이 경로 따라가기",
  ["Coming steps"] = "다음 단계",
  ["Compass in the current step"] = "현재 단계의 나침반",
  ["Ctrl + mouse wheel: text size."] = "Ctrl + 마우스 휠: 글자 크기.",
  ["Darkspear"] = "검은창",
  ["Do"] = "수행",
  ["Do along here: %s (%s)"] = "여기서 함께 수행: %s (%s)",
  ["Done: take me to the trainers"] = "완료: 훈련사에게 안내해 주세요",
  ["Drag: width (right, left) and how many coming steps (down, up)."] = "드래그: 너비(오른쪽, 왼쪽)와 다음 단계 수(아래, 위).",
  ["Dun Morogh (Dwarf, Gnome)"] = "던 모로 (드워프, 노움)",
  ["Dungeon %s fits your level (%d quests): /lvd dungeon to plan it, /lvd dungeon no to skip"] = "던전 %s: 레벨에 맞습니다 (퀘스트 %d개). /lvd dungeon : 계획, /lvd dungeon no : 건너뛰기",
  ["Dungeons in the route"] = "경로 속 던전",
  ["Durotar (Orc, Troll)"] = "듀로타 (오크, 트롤)",
