  ["|cff3fa9f5Level|rdon: \"%s\" needs level %d. It comes back when the route passes this place again."] = "|cff3fa9f5Level|rdon: \"%s\" 퀘스트에는 레벨 %d가 필요합니다. 경로가 이곳을 다시 지나갈 때 돌아옵니다.",
  ["|cff3fa9f5Level|rdon: \"%s\" skipped. One step back brings it back."] = "|cff3fa9f5Level|rdon: \"%s\" 퀘스트를 건너뛰었습니다. 한 단계 뒤로 가면 되돌아옵니다.",
  ["|cff3fa9f5Level|rdon: %s took %d s (waited %d s), noted for /lvd export."] = "|cff3fa9f5Level|rdon: %s: %d초 (대기 %d초), /lvd export용으로 기록했습니다.",
  ["|cff3fa9f5Level|rdon: before you go: "] = "|cff3fa9f5Level|rdon: 가기 전에: ",
