  ["|cff3fa9f5Level|rdon: route started again from your level."] = "|cff3fa9f5Level|rdon: 현재 레벨부터 경로를 다시 시작했습니다.",
  ["|cff3fa9f5Level|rdon: sharing %s (sent %d, received %d facts, %d kept). /lvd share on|off"] = "|cff3fa9f5Level|rdon: 공유 %s (보냄 %d, 받음 %d건, %d건 보관). /lvd share on|off",
  ["|cff3fa9f5Level|rdon: sleeping bag reminder "] = "|cff3fa9f5Level|rdon: 침낭 알림 ",
  ["|cff3fa9f5Level|rdon: solo "] = "|cff3fa9f5Level|rdon: 솔로 ",
  ["|cff3fa9f5Level|rdon: target markers "] = "|cff3fa9f5Level|rdon: 대상 표시 ",
  ["|cff3fa9f5Level|rdon: text size %d %% (Ctrl + mouse wheel over the title bar, /lvd text 1.3)."] = "|cff3fa9f5Level|rdon: 글자 크기 %d %% (제목 표시줄 위에서 Ctrl + 마우스 휠, /lvd text 1.3).",
  ["|cff3fa9f5Level|rdon: the marks over NPCs need the nameplates of friendly NPCs (interface options, Names)."] = "|cff3fa9f5Level|rdon: NPC 위 표시를 보려면 우호적인 NPC의 이름표를 켜세요 (인터페이스 옵션, 이름).",
  ["|cff3fa9f5Level|rdon: the options window needs Questdon 1.3.9 or newer. Until then: /lvd commands."] = "|cff3fa9f5Level|rdon: 설정 창에는 Questdon 1.3.9 이상이 필요합니다. 그때까지: /lvd 명령어.",
  ["|cff3fa9f5Level|rdon: writing along %s. %d sessions, %d events, %d walking points, %d reports kept (/lvd rec on|off)."] = "|cff3fa9f5Level|rdon: 기록 %s. 세션 %d개, 이벤트 %d개, 이동 지점 %d개, 신고 %d개 보관 (/lvd rec on|off).",
  ["|cff3fa9f5Level|rdon: you are ahead on the route; it goes on at \"%s\"."] = "|cff3fa9f5Level|rdon: 경로보다 앞서 있습니다. \"%s\"에서 계속됩니다.",
  ["|cff3fa9f5Level|rdon: you have the %s for riding now: visit the riding trainer."] = "|cff3fa9f5Level|rdon: 기마술에 필요한 금액을 모았습니다 (%s): 기마술 훈련사를 방문하세요.",
  ["|cff3fa9f5Level|rdon: you learned %s: its steps are in your route now."] = "|cff3fa9f5Level|rdon: %s 배움: 관련 단계가 이제 경로에 있습니다.",
  -- (25.10.) only record (Options.lua SetRecordOnly)
  ["Only record your run"] = "진행 기록만",
  ["On / off"] = "켜기 / 끄기",
  ["Hides the window and switches off what Leveldon shows or marks by itself (markers over NPCs, bag frames, reminders); the recording and the shared route times stay on, so your run still helps the routes. Click again and the window and your settings are back. Also /lvd quiet."] = "창을 숨기고 Leveldon이 스스로 표시하거나 표시하는 것(NPC 위 표식, 가방 테두리, 알림)을 끕니다. 기록과 경로 시간 공유는 계속 켜져 있어 진행이 계속 경로 개선에 도움이 됩니다. 다시 클릭하면 창과 설정이 돌아옵니다. /lvd quiet로도 가능합니다.",
  ["|cff3fa9f5Level|rdon only records your run now. /lvd quiet brings the window and your settings back."] = "|cff3fa9f5Level|rdon이 이제 진행만 기록합니다. /lvd quiet로 창과 설정을 되돌립니다.",
  ["|cff3fa9f5Level|rdon: window and settings are back."] = "|cff3fa9f5Level|rdon: 창과 설정이 돌아왔습니다.",
  -- (25.10.) window values, key (Options.lua, Leveldon.lua)
  ["Lock window"] = "창 고정",
  ["The window can no longer be dragged."] = "창을 더 이상 옮길 수 없습니다.",
  ["Size"] = "크기",
  ["Size of the whole window and its text. Ctrl + mouse wheel over the window does the same."] = "창 전체와 글자의 크기입니다. 창 위에서 Ctrl + 마우스 휠로도 바꿀 수 있습니다.",
  ["Background opacity"] = "배경 불투명도",
  ["How dark the window's background is. Shift + mouse wheel over the window does the same."] = "창 배경의 어두운 정도입니다. 창 위에서 Shift + 마우스 휠로도 바꿀 수 있습니다.",
  ["Dim in combat"] = "전투 중 흐리게",
  ["The window fades to a little more than a third of its strength while you fight."] = "전투 중에는 창이 원래 세기의 3분의 1 조금 넘게 흐려집니다.",
  ["Reset window position"] = "창 위치 초기화",
  ["Reset"] = "초기화",
  ["Puts Leveldon's window back to its starting place. The key for it: Key Bindings > AddOns > Leveldon."] = "Leveldon 창을 처음 위치로 되돌립니다. 단축키: 단축키 설정 > 애드온 > Leveldon.",
  ["Show or hide the window"] = "창 표시/숨기기",
  -- (25.10.) arrow instead of the compass (Options.lua)
  ["Arrow instead of the compass"] = "나침반 대신 화살표",
  ["Questdon's direction arrow leads you to the step instead of the compass in Leveldon's window and in the quest list. Switch off again and the compass and your earlier arrow settings come back. It changes Questdon's settings for all your characters."] = "Leveldon 창과 퀘스트 목록의 나침반 대신 Questdon의 방향 화살표가 단계까지 안내합니다. 다시 끄면 나침반과 이전 화살표 설정이 돌아옵니다. 모든 캐릭터의 Questdon 설정이 바뀝니다.",
  ["Arrow: no background and frame"] = "화살표: 배경과 테두리 없음",
  ["Hides the plate and frame behind the arrow's text: only the arrow and the writing stay. Same as Questdon's option for the arrow."] = "화살표 글자 뒤의 판과 테두리를 숨깁니다. 화살표와 글자만 남습니다. Questdon의 화살표 옵션과 같습니다.",
  ["|cff3fa9f5Level|rdon: the arrow option needs Questdon 1.3.11 or newer."] = "|cff3fa9f5Level|rdon: 화살표 옵션에는 Questdon 1.3.11 이상이 필요합니다.",
}
